function record(level, ...args) {
        const receivedMonoMs = performance.now();
        const message = args.map(format).join(' ').slice(0, legacyMessageLimit);
        entries.push({
            value: { time: new Date().toISOString(), level, message },
            receivedMonoMs,
        });
        while (entries.length && (entries[0].receivedMonoMs < receivedMonoMs - logWindowMs || entries.length > legacyEntryLimit)) {
            entries.shift();
            dropped++;
        }
        if (level === 'error') appendShellEvent('diagnostic_exception', { level, message });
    }
